-- Schema: offers
CREATE TABLE offers (
	offer_id VARCHAR(30) NOT NULL,
	offer_name VARCHAR(150) NOT NULL,
	offer_type VARCHAR(50) NOT NULL,
	discount_pct FLOAT NOT NULL,
	discount_amount FLOAT NOT NULL,
	max_offer_cost FLOAT NOT NULL,
	eligible_plans VARCHAR(255) NOT NULL,
	min_tenure_months INTEGER NOT NULL,
	min_subscription_mrr FLOAT NOT NULL,
	max_discount_cap FLOAT NOT NULL,
	valid_from DATETIME NOT NULL,
	valid_to DATETIME NOT NULL,
	status VARCHAR(20) NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (offer_id),
	CONSTRAINT chk_offer_type_valid CHECK (offer_type IN ('Discount', 'Free_Month', 'Feature_Addon', 'Tier_Upgrade')),
	CONSTRAINT chk_offer_status_valid CHECK (status IN ('Draft', 'Active', 'Paused', 'Expired')),
	CONSTRAINT chk_offer_discount_pct_range CHECK (discount_pct >= 0 AND discount_pct <= 100),
	CONSTRAINT chk_offer_discount_amt_positive CHECK (discount_amount >= 0),
	CONSTRAINT chk_offer_cost_positive CHECK (max_offer_cost >= 0)
);

-- Schema: eligibility_rules
CREATE TABLE eligibility_rules (
	rule_id VARCHAR(40) NOT NULL,
	offer_id VARCHAR(30) NOT NULL,
	rule_code VARCHAR(50) NOT NULL,
	parameter_name VARCHAR(100) NOT NULL,
	operator VARCHAR(20) NOT NULL,
	parameter_value VARCHAR(255) NOT NULL,
	margin_threshold_pct FLOAT NOT NULL,
	is_active BOOLEAN NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (rule_id),
	CONSTRAINT chk_rule_operator_valid CHECK (operator IN ('GT', 'GTE', 'LT', 'LTE', 'EQ', 'IN', 'NOT_IN')),
	CONSTRAINT chk_rule_margin_range CHECK (margin_threshold_pct >= 0 AND margin_threshold_pct <= 1.0),
	FOREIGN KEY(offer_id) REFERENCES offers (offer_id) ON DELETE CASCADE
);

-- Schema: customers
CREATE TABLE customers (
	customer_id VARCHAR(20) NOT NULL,
	first_name VARCHAR(100) NOT NULL,
	last_name VARCHAR(100) NOT NULL,
	email VARCHAR(255) NOT NULL,
	company_name VARCHAR(255) NOT NULL,
	industry VARCHAR(100) NOT NULL,
	customer_tier VARCHAR(50) NOT NULL,
	cohort_month VARCHAR(7) NOT NULL,
	signup_date DATETIME NOT NULL,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (customer_id)
);

-- Schema: subscriptions
CREATE TABLE subscriptions (
	subscription_id VARCHAR(30) NOT NULL,
	customer_id VARCHAR(20) NOT NULL,
	plan_name VARCHAR(50) NOT NULL,
	billing_cycle VARCHAR(20) NOT NULL,
	mrr FLOAT NOT NULL,
	unit_cost FLOAT NOT NULL,
	status VARCHAR(30) NOT NULL,
	start_date DATETIME NOT NULL,
	end_date DATETIME,
	trial_end_date DATETIME,
	canceled_at DATETIME,
	churn_reason VARCHAR(50) NOT NULL,
	plan_change_count INTEGER NOT NULL,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (subscription_id),
	CONSTRAINT chk_subscription_mrr_positive CHECK (mrr >= 0),
	CONSTRAINT chk_subscription_unit_cost_positive CHECK (unit_cost >= 0),
	CONSTRAINT chk_subscription_status_valid CHECK (status IN ('Active', 'Delinquent', 'Canceled', 'Expired', 'Paused')),
	CONSTRAINT chk_subscription_churn_reason_valid CHECK (churn_reason IN ('Voluntary', 'Involuntary', 'None')),
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE
);

-- Schema: usage_snapshots
CREATE TABLE usage_snapshots (
	snapshot_id VARCHAR(45) NOT NULL,
	subscription_id VARCHAR(30) NOT NULL,
	snapshot_month VARCHAR(7) NOT NULL,
	snapshot_date DATETIME NOT NULL,
	active_days INTEGER NOT NULL,
	login_count INTEGER NOT NULL,
	total_session_minutes FLOAT NOT NULL,
	feature_events_count INTEGER NOT NULL,
	api_call_count INTEGER NOT NULL,
	license_utilization_pct FLOAT NOT NULL,
	usage_decline_pct FLOAT NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (snapshot_id),
	CONSTRAINT uq_subscription_month_snapshot UNIQUE (subscription_id, snapshot_month),
	CONSTRAINT chk_usage_active_days CHECK (active_days >= 0 AND active_days <= 31),
	CONSTRAINT chk_usage_login_count CHECK (login_count >= 0),
	CONSTRAINT chk_usage_session_mins CHECK (total_session_minutes >= 0),
	CONSTRAINT chk_usage_features CHECK (feature_events_count >= 0),
	CONSTRAINT chk_usage_api_calls CHECK (api_call_count >= 0),
	CONSTRAINT chk_usage_license_pct CHECK (license_utilization_pct >= 0 AND license_utilization_pct <= 100),
	FOREIGN KEY(subscription_id) REFERENCES subscriptions (subscription_id) ON DELETE CASCADE
);

-- Schema: billing_events
CREATE TABLE billing_events (
	billing_id VARCHAR(30) NOT NULL,
	subscription_id VARCHAR(30) NOT NULL,
	billing_date DATETIME NOT NULL,
	due_date DATETIME NOT NULL,
	invoice_amount FLOAT NOT NULL,
	paid_amount FLOAT NOT NULL,
	status VARCHAR(30) NOT NULL,
	retry_count INTEGER NOT NULL,
	failure_reason VARCHAR(100) NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (billing_id),
	CONSTRAINT chk_billing_invoice_positive CHECK (invoice_amount >= 0),
	CONSTRAINT chk_billing_paid_positive CHECK (paid_amount >= 0),
	CONSTRAINT chk_billing_status_valid CHECK (status IN ('Paid', 'Pending', 'Failed', 'Refunded')),
	CONSTRAINT chk_billing_retries_positive CHECK (retry_count >= 0),
	FOREIGN KEY(subscription_id) REFERENCES subscriptions (subscription_id) ON DELETE CASCADE
);

-- Schema: support_cases
CREATE TABLE support_cases (
	case_id VARCHAR(30) NOT NULL,
	customer_id VARCHAR(20) NOT NULL,
	category VARCHAR(50) NOT NULL,
	priority VARCHAR(20) NOT NULL,
	status VARCHAR(30) NOT NULL,
	opened_at DATETIME NOT NULL,
	resolved_at DATETIME,
	resolution_hours FLOAT,
	escalation_count INTEGER NOT NULL,
	csat_score INTEGER,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (case_id),
	CONSTRAINT chk_support_category_valid CHECK (category IN ('Billing', 'Technical', 'Product_Bug', 'Feature_Request', 'Account')),
	CONSTRAINT chk_support_priority_valid CHECK (priority IN ('Low', 'Medium', 'High', 'Critical')),
	CONSTRAINT chk_support_status_valid CHECK (status IN ('Open', 'In_Progress', 'Resolved', 'Escalated')),
	CONSTRAINT chk_support_csat_range CHECK (csat_score IS NULL OR (csat_score >= 1 AND csat_score <= 5)),
	CONSTRAINT chk_support_escalations_positive CHECK (escalation_count >= 0),
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE
);

-- Schema: campaign_contacts
CREATE TABLE campaign_contacts (
	contact_id VARCHAR(30) NOT NULL,
	experiment_id VARCHAR(50) NOT NULL,
	customer_id VARCHAR(20) NOT NULL,
	offer_id VARCHAR(30),
	experiment_group VARCHAR(20) NOT NULL,
	stratum_id VARCHAR(100) NOT NULL,
	assigned_at DATETIME NOT NULL,
	delivery_date DATETIME,
	delivery_channel VARCHAR(30) NOT NULL,
	delivery_status VARCHAR(30) NOT NULL,
	is_eligible BOOLEAN NOT NULL,
	eligibility_notes TEXT,
	response_date DATETIME,
	response_status VARCHAR(30) NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (contact_id),
	CONSTRAINT uq_experiment_customer_assignment UNIQUE (experiment_id, customer_id),
	CONSTRAINT chk_campaign_experiment_group_valid CHECK (experiment_group IN ('Treatment', 'Control')),
	CONSTRAINT chk_campaign_delivery_channel_valid CHECK (delivery_channel IN ('Email', 'In_App', 'CSM_Outreach')),
	CONSTRAINT chk_campaign_delivery_status_valid CHECK (delivery_status IN ('Sent', 'Delivered', 'Failed', 'Suppressed')),
	CONSTRAINT chk_campaign_response_status_valid CHECK (response_status IN ('Accepted', 'Rejected', 'Ignored', 'Pending')),
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE,
	FOREIGN KEY(offer_id) REFERENCES offers (offer_id) ON DELETE SET NULL
);

-- Schema: churn_outcomes
CREATE TABLE churn_outcomes (
	churn_id VARCHAR(30) NOT NULL,
	customer_id VARCHAR(20) NOT NULL,
	subscription_id VARCHAR(30) NOT NULL,
	prediction_cutoff_date DATETIME NOT NULL,
	observation_window_start DATETIME NOT NULL,
	observation_window_end DATETIME NOT NULL,
	actual_churned BOOLEAN NOT NULL,
	actual_churn_date DATETIME,
	churn_type VARCHAR(30) NOT NULL,
	primary_churn_driver VARCHAR(50) NOT NULL,
	is_ground_truth BOOLEAN NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (churn_id),
	CONSTRAINT uq_customer_cutoff_churn UNIQUE (customer_id, prediction_cutoff_date),
	CONSTRAINT chk_churn_type_valid CHECK (churn_type IN ('Voluntary', 'Involuntary', 'Retained')),
	CONSTRAINT chk_churn_driver_valid CHECK (primary_churn_driver IN ('Usage_Drop', 'Payment_Failure', 'Support_Frustration', 'Competitor', 'None')),
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE,
	FOREIGN KEY(subscription_id) REFERENCES subscriptions (subscription_id) ON DELETE CASCADE
);

-- Schema: retention_outcomes
CREATE TABLE retention_outcomes (
	retention_id VARCHAR(35) NOT NULL,
	contact_id VARCHAR(30) NOT NULL,
	customer_id VARCHAR(20) NOT NULL,
	churn_id VARCHAR(30),
	retained_after_horizon BOOLEAN NOT NULL,
	days_retained INTEGER NOT NULL,
	incremental_revenue FLOAT NOT NULL,
	offer_cost_incurred FLOAT NOT NULL,
	net_campaign_value FLOAT NOT NULL,
	attribution_status VARCHAR(50) NOT NULL,
	evaluated_at DATETIME NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (retention_id),
	CONSTRAINT chk_retention_attribution_valid CHECK (attribution_status IN ('Primary_Attributed', 'Multi_Attributed_Flagged', 'Non_Attributed')),
	CONSTRAINT chk_retention_days_positive CHECK (days_retained >= 0),
	FOREIGN KEY(contact_id) REFERENCES campaign_contacts (contact_id) ON DELETE CASCADE,
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE,
	FOREIGN KEY(churn_id) REFERENCES churn_outcomes (churn_id) ON DELETE SET NULL
);

